window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-gineco-e-obstetricia-med-gin-05"]={"block":"med:med-gineco-e-obstetricia-med-gin-05","label":"MED · MED GIN 05","count":45,"questions":[{"id":"med-gineco-e-obstetricia-med-gin-05-84455","number":"84455","sourceNumber":"84455","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Sobre o tratamento clínico da endometriose, considere as seguintes afirmativas: 1.\nPode ser efetivo com o uso contínuo de\ncontraceptivos orais. 2. Utilizando-se progestogênios,\ngestrinona, danazol ou análogos do hormônio de liberação da gonadotrofina (GnRH), é igualmente\nefetivo para alívio da dor associada à endometriose. 3. Melhora a infertilidade associada à\nendometriose. 4. Resulta em supressão prolongada da doença (no mínimo dois anos) e em alívio\nda dor após a interrupção do tratamento. Assinale a alternativa CORRETA.","options":{"A":"Somente as afirmativas 1 e 3 são verdadeiras.","B":"Somente as afirmativas 2 e 4 são verdadeiras.","C":"Somente as afirmativas 1 e 2 são verdadeiras.","D":"Somente as afirmativas 2, 3 e 4 são verdadeiras.","E":"As afirmativas 1, 2, 3 e 4 são verdadeiras."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-84519","number":"84519","sourceNumber":"84519","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Paciente de 48 anos foi submetida à histerectomia total abdominal e vem apresentando\nsintomas vasomotores (fogachos) e alterações do\nhumor e sono há aproximadamente 1 ano. Na\ndosagem sanguínea das gonadotrofinas hipofisárias e esteroides ovarianos para CONFIGURAR O\nCLIMATÉRIO, ESPERA-SE:","options":{"A":"Aumento do estradiol e do FSH;","B":"Estradiol inalterado e queda do FSH;","C":"Queda do estradiol e do FSH;","D":"Queda do estradiol e aumento do FSH;","E":"Queda do estradiol e FSH inalterado."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-249309","number":"249309","sourceNumber":"249309","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"A droga que pode diminuir a eficácia do anticoncepcional combinado oral é:","options":{"A":"pirazinamida","B":"etambutol","C":"sulfadiazina","D":"fenobarbital"},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-249313","number":"249313","sourceNumber":"249313","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Dos métodos anticoncepcionais, aquele com maior potencial trombogênico é:","options":{"A":"injetável trimestral","B":"injetável mensal","C":"anticoncepcional combinado oral","D":"anel vaginal"},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-249241","number":"249241","sourceNumber":"249241","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Na anatomia vascular uterina, partindo da artéria uterina, a sequência correta é:","options":{"A":"artéria arqueada > artéria radial > artéria espiralada.","B":"artéria radial > artéria espiralada > artéria arqueada.","C":"artéria espiralada > artéria radial > artéria arqueada.","D":"artéria radial > artéria arqueada > artéria espiralada."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-216357","number":"216357","sourceNumber":"216357","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Mulher usuária de anticoncepcional combinado oral, pergunta ao ginecologista a\nrespeito da interação medicamentosa dos anticoncepcionais com outras drogas. Aquela que,\nsabidamente não interfere com estes anticoncepcionais, é","options":{"A":"Carbamazepina.","B":"Benzodiazepínico.","C":"Ampicilina.","D":"Ácido valpróico."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-86845","number":"86845","sourceNumber":"86845","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"O diagnóstico de endometriose é confirmado histológicamente através da identificação\nde implantes extragenitais contendo:","options":{"A":"Glândulas endometriais e estroma;","B":"Músculo liso hipertrófico;","C":"Hemorragia e depósitos de pegmento de ferro;","D":"Fibose;","E":"Estroma decíduo."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-86604","number":"86604","sourceNumber":"86604","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"A causa mais comum de sangramento genital pós-menopausa é:","options":{"A":"Pólipo endometrial.","B":"Câncer de endométrio.","C":"Atrofia do endométrio.","D":"Hiperplasia endometrial.","E":"N.D.A."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-81962","number":"81962","sourceNumber":"81962","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Paciente de 43 anos, G2, P2, apresenta hiperpolimenorreia há dois anos e\ndismenorreia há seis meses. Qual a propedêutica\nmais adequada para começar a investigação?","options":{"A":"Colpocitologia, histeroscopia e Tomografia Computadorizada (TC).","B":"Exame especular, toque bimanual e ultrassonografia.","C":"Toque bimanual, TC e curetagem uterina.","D":"Histeroscopia, Ressonância Nuclear Magnética (RNM) da pelve e TC.","E":"Colpocitologia, RNM da pelve e curetagem."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-81927","number":"81927","sourceNumber":"81927","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"São indicações para o uso do análogo do GnRH no mioma uterino, EXCETO:","options":{"A":"Preservação da fertilidade.","B":"Permitir a recuperação dos níveis normais de hemoglobina antes da cirurgia .","C":"Pacientes na perimenopausa.","D":"Pré-operatório para redução de grandes miomas e permitir histerectomia vaginal.","E":"Aumento do útero em mulher na pós-menopausa."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-46654","number":"46654","sourceNumber":"46654","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"São Fatores de Risco Modificáveis na Osteoporose, EXCETO:","options":{"A":"Raça branca.","B":"Baixo peso.","C":"Baixa ingestão de cálcio.","D":"Corticoterapia prolongada.","E":"Consumo excessivo de bebibas alcoólicas e café."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-284605","number":"284605","sourceNumber":"284605","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Mulher branca, 60 anos de idade, desde os 45 anos de idade entrou na menopausa. A\nprimeira menstruação ocorreu aos 9 anos. Teve 3 gestações e todas evoluíram para parto normal.\nRefere hipertensão bem controlada com medicação. IMC: 30Kg/m². Vem ao pronto atendimento\npois apresentou sangramento vaginal, de pouca quantidade, há 3 dias, com melhora espontânea\napós 2 dias do início do evento. Hoje apresenta sangramento tipo borra de café. Nega cólica ou\noutros sintomas associados. Nega uso de medicações no momento ou histórico de reposição\nhormonal. Ao exame físico: corada e hidratada. Abdome flácido, indolor à palpação e sem\nvisceromegalias. Exame especular: presença de sangramento não ativo de pouca quantidade\ncoletado em fundo vaginal. TV: ausência de dor à mobilização do colo uterino. Ultrassonografia\nTransvaginal realizada evidencia útero em retroversoflexão com dimensões, morfologia e contornos\npreservados. Medida total: 40cm³, miométrio com ecotextura homogênea, eco endometrial centrado\nhomogêneo de 6mm. Ovários não visualizados. Ausência de líquido livre na cavidade. Diante do\nresultado da ultrassonografia transvaginal é correto afirmar:","options":{"A":"A ultrassonografia transvaginal está normal e a conduta deve ser expectante.","B":"A paciente deverá ser submetida à histeroscopia com biópsia endometrial, mesmo com a\nultrassonografia sem alterações.","C":"A ultrassonografia evidencia um endométrio espessado e a conduta deverá ser realização de\nbiópsia endometrial.","D":"A ultrassonografia transvaginal está normal e, provavelmente, a paciente apresenta um\nsangramento uterino anormal de causa ovariana\ne devem ser solicitados exames laboratoriais para\nmelhor avaliação."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-250005","number":"250005","sourceNumber":"250005","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Mulher de 34 anos que fuma 20 cigarros por dia, segundo critérios da OMS de\nelegibilidade para uso de anticoncepcionais, para uso de pílula contendo estrogênio e\nprogesterona, estaria enquadrada na categoria:","options":{"A":"1","B":"2","C":"3","D":"4"},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-81299","number":"81299","sourceNumber":"81299","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Mulher, 38 anos, casada, manicure, G3P2A1, tem DM tipo I, controlada. Deseja fazer\nuso de contracepção segura e eficaz. Qual a\nopção contraceptiva mais aconselhável?","options":{"A":"Anel vaginal.","B":"Injetável trimestral.","C":"Adesivo transdérmico.","D":"Contraceptivo oral combinado."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-51115","number":"51115","sourceNumber":"51115","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Uma menina de 5 anos de idade apresenta sangramento genital. Não tem aumento de\nmamas ou pelos pubianos. Qual a causa mais\nfrequente de sangramento genital neste caso?","options":{"A":"Abuso sexual.","B":"Vulvovaginite.","C":"Corpo estranho.","D":"Puberdade precoce."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-214386","number":"214386","sourceNumber":"214386","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Uma paciente de 38 anos de idade está vivenciando a primeira gestação dela e seguiu\no acompanhamento gestacional com a respectiva\nobstetra, realizando regularmente os exames\nlaboratoriais conforme preconizados pelo Ministério da Saúde. Segue a lista de alguns dos exames\nrealizados ao longo da gestação, transcritos não necessariamente na ordem cronológica de\nrealização: cultura para Streptococcus do grupo B por meio de swab retovaginal: positiva; teste oral\nde tolerância à glicose: jejum: 80 mg/dL - após uma hora; 172 mg/dL - após duas horas: 156 mg/dL;\nsorologias para toxoplasmose: IgG negativo e IgM positivo; VDRL: negativo; anti-HIV: negativo;\nultrassonografia morfológica fetal: circunferência cefálica com -3,2 desvios-padrões em relação à\nmédia para a idade gestacional. Sem outras alterações. Acerca da avaliação laboratorial\ngestacional rotineira e dos possíveis impactos dos respectivos achados, e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. Em razão do achado de microcefalia na\nultrassonografia morfológica fetal, é correto orientar a paciente acerca do direito de realizar\ninterrupção da gestação, conforme resolução do Supremo Tribunal Federal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-135032","number":"135032","sourceNumber":"135032","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Julgue o item subsecutivo, que trata de distúrbios endócrinos, hematológicos,\nreumatológicos e renais encontrados com\nfrequência em pacientes que procuram ambulatório de\nginecologia. Mulheres jovens portadoras de lúpus eritematoso sistêmico (LES), com queixa de\nsangramento uterino anormal cursando com anemia crônica e níveis séricos de ferritina baixo e\npresença de anticorpos antifosfolipídios, são boas candidatas ao uso de anticoncepcionais orais\ncombinados.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-108187","number":"108187","sourceNumber":"108187","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Julgue o próximo item, referente a planejamento familiar e assistência pré-natal. O\netinilestradiol, estrogênio mais utilizado nos anticoncepcionais hormonais orais combinados,\nprovoca o aumento das proteínas hepáticas e do substrato da renina, o que, por sua vez,\ndesencadeia a vasoconstricção e a retenção de sódio e de água.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-82122","number":"82122","sourceNumber":"82122","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Com relação à endocrinologia reprodutiva, julgue o item a seguir. Na fase folicular do\nciclo menstrual normal, o folículo primordial é um ovócito, margeado pela zona translúcida, cujo\ncrescimento é dependente da estimulação das gonadotrofinas, principalmente de hormônio folículo\nestimulante (FSH).","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-82089","number":"82089","sourceNumber":"82089","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Considerando as políticas públicas brasileiras voltadas à saúde da mulher, julgue o item\nsubsecutivo. A atenção em anticoncepção pressupõe a oferta de informações, de aconselhamento,\nde acompanhamento clínico e de métodos e técnicas anticoncepcionais, cientificamente aceitos,\nque não coloquem em risco a vida e a saúde das pessoas, e, de acordo com os critérios\nestabelecidos, o profissional de saúde é quem deve escolher o método mais apropriado às\nnecessidades do paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-49181","number":"49181","sourceNumber":"49181","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"A respeito de ginecologia, julgue o item seguinte. Nas pacientes com diagnóstico de\nsíndrome de climatério, a elevação do hormônio folículoestimulante (FSH) é patognomônica.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-266496","number":"266496","sourceNumber":"266496","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Alice, com 16 anos de idade, questionou, durante consulta médica, sobre a\npossibilidade de colocar um DIU na UBS,\npois tivera relação sexual desprotegida havia cerca de\nquatro dias. Ao médico ela relatou que a sua última menstruação havia ocorrido 15 dias atrás e que\no seu ciclo menstrual era irregular, de 20 a 28 dias, com 7 dias de fluxo normal, sem cólicas. Tendo\ncomo referência esse caso clínico hipotético, julgue o item subsecutivo. A inserção do DIU TCu\n380A é opção adequada como método contraceptivo de emergência para o caso em questão,\ntendo maior eficácia se realizada em até cinco dias após o ato sexual desprotegido.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-30994","number":"30994","sourceNumber":"30994","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Julgue o próximo item, relativo a planejamento familiar e infertilidade conjugal. Nos\ncritérios médicos de elegibilidade, indicados\npela Organização Mundial de Saúde (OMS) para uso\nde métodos anticoncepcionais, a categoria 2 enquadra-se na condição em que os riscos teóricos ou\ncomprovados geralmente se sobrepõem às vantagens do uso do método.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-368153","number":"368153","sourceNumber":"368153","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Algumas cardiopatias geram um risco adicional elevado durante a gestação e puerpério\ndevido à sobrecarga hemodinâmica causada pelas modificações adaptativas da gestação.\n\nEntretanto, a maioria das mulheres cardiopatas não recebe orientação quanto à contracepção. A\nescolha do método contraceptivo deve levar em conta particularidades de cada patologia específica\npara reduzir os riscos. Nesse contexto, analise as afirmativas a seguir sobre a contracepção da\nmulher cardiopata. I. Pacientes com alto risco trombogênico (cardiopatias congênitas complexas,\nICFER com FE < 30%, valvopatas e próteses mecânicas), assim como hipertensas graves, não\ndevem utilizar métodos hormonais. II. Pacientes em que a retenção hídrica seja um problema\ndevem evitar métodos de progesterona. III. Pacientes com arritmia ou outra condição que necessite\nanticoagulação podem usar DIU de cobre sem risco de aumento do sangramento. IV. Pacientes\ndas classes III e IV da classificação de risco materno da OMS têm indicação de uso de métodos de\ncontracepção reversível de longa duração (LARC), pela maior segurança e menor índice de falha.\n\nEstão corretas as afirmativas","options":{"A":"I e II, apenas.","B":"II e IV, apenas.","C":"I e III, apenas.","D":"I, II, III e IV."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-260683","number":"260683","sourceNumber":"260683","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Paciente de 32 anos, nuligesta, procura consultório de ginecologia com queixa de\naumento da quantidade e da duração do\nsangramento menstrual nos últimos 6 meses. Na\navaliação diagnóstica o único achado anormal foi a presença de um mioma de 2 cm submucoso. A\nmelhor conduta para essa paciente é:","options":{"A":"miomectomia laparoscópica.","B":"histerectomia.","C":"miomectomia histeroscópica.","D":"embolização de artérias uterinas.","E":"análogos de GnRH."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-255638","number":"255638","sourceNumber":"255638","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Samara, 27 anos, apresenta a síndrome do ovário policístico, diagnosticada há 3 anos,\nainda não tratada pois os sintomas estavam brandos. No entanto, a oligomenorréia está\nprovocando bastante incômodo nos últimos meses. Qual dos tipos de anticoncepcionais orais\ncombinados oferece menor risco para Trombose Venosa Profunda a Samara? MARQUE A\nCORRETA:","options":{"A":"Levonorgestrel + estradiol","B":"Drospirenona + estradiol","C":"Desogestrel + estradiol","D":"Norgestimato + estradiol"},"answer":"A","answerPending":false,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-227267","number":"227267","sourceNumber":"227267","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Mulher com história de trombose venosa profunda, tratada há mais de 5 anos com\nEnoxaparina®, sem necessidade de trombectomia, não deseja gestar. Qual desses métodos\ncontraceptivos é o mais indicado para a paciente?","options":{"A":"Anovulatório hormonal combinado injetável mensal.","B":"Anovulatório de progesterona injetável trimestral.","C":"Anovulatório hormonal combinado tipo anel vaginal.","D":"Anovulatório hormonal combinado tipo adesivo transdérmico."},"answer":"B","answerPending":false,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-246757","number":"246757","sourceNumber":"246757","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Uma paciente acabou de ter seu primeiro filho. Ela está ansiosa para amamentá-lo.\nComo parte de suas orientações de alta após o\nparto, ela deve ser informada de que poucas coisas\ninterferem com a lactação, mas que deve evitar:","options":{"A":"Pílulas combinadas.","B":"Implantes de levonorgestrel.","C":"Depo-Provera.","D":"Minipílula.","E":"Condon."},"answer":"A","answerPending":false,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-246764","number":"246764","sourceNumber":"246764","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Paciente de 38 anos, 3 Gesta 2 Para 1 Aborto, vem para consulta ginecológica de\nrotina, informando que seu último exame\npreventivo ginecológico foi há 4 anos e era normal. É\ntabagista de, pelo menos, 22 cigarros por dia há cerca de 15 anos. Usa pílula anticoncepcional\ncombinada composta por etinilestradiol 30 mcg e levonorgestrel 100 mcg por drágea há alguns\nanos, bem adaptada e sem nenhum efeito adverso. Nega doenças e apresenta boa saúde. Exame\nfísico e ginecológico, sem anormalidades. Após realizar coleta da colpocitologia o ginecologista a\nfim de orientá-la sobre anticoncepção deve:","options":{"A":"Informá-la de que a pílula anticoncepcional combinada está contraindicada por ela ser tabagista\ne ter mais de 35 anos e pode recomendar o uso\nde outros métodos hormonais combinados, desde\nque administrados por via não oral.","B":"Aconselhá-la a manter a pílula anticoncepcional combinada de baixa dose hormonal que ela já\nutiliza, pois além de ela já estar bem adaptada, nunca teve evento adverso que a contraindicasse.","C":"Informá-la de que a pílula anticoncepcional combinada está contraindicada por ela ser tabagista\ne ter mais de 35 anos e pode recomendar o uso\nde método hormonal apenas com progestagênio.","D":"Informá-la de que o tabagismo é contraindicação absoluta ao uso de pílula anticoncepcional\ncombinada e esclarecer que ela nunca deveria\nter utilizado este método, mesmo quando jovem.","E":"Nenhuma das alternativas anteriores está correta."},"answer":"C","answerPending":false,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-199587","number":"199587","sourceNumber":"199587","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"De acordo com a OMS (Organização Mundial de Saúde) não é contraindicação\nabsoluta para a inserção do DIU (Dispositivo Intra\nUterino):","options":{"A":"Gravidez.","B":"Infecção por HIV.","C":"Câncer de endométrio.","D":"Doença inflamatória pélvica atual."},"answer":"B","answerPending":false,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-199557","number":"199557","sourceNumber":"199557","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Devido a alguns efeitos benéficos para a saúde, a contracepção hormonal é muitas\nvezes usada para finalidades não anticoncepcionais. Não é efeito benéfico dos contraceptivos\nhormonais combinados:","options":{"A":"Redução da dismenorreia.","B":"Redução do câncer de mama.","C":"Regulação da perda sanguínea menstrual.","D":"Redução dos distúrbios disfóricos pré-menstruais."},"answer":"B","answerPending":false,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-174396","number":"174396","sourceNumber":"174396","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"?No Brasil, a gravidez não planejada ainda é um problema de saúde pública, mesmo\ncom o avanço na medicina reprodutiva e\nmétodos anticoncepcionais cada vez mais modernos. Nas\ncamadas sociais menos favorecidas, as mulheres em situação de vulnerabilidade estão cada vez\nmais expostas às mazelas da miséria e da violência sexual, principalmente as adolescentes. E o\ncusto desta situação tem causado sérios prejuízos ao país: R$ 4,1 bilhões anuais, segundo o\nprofessor Luis Guillermo Bahamondes, ginecologista da Unicamp.?\nhttps://noticias.r7.com/saude/gravidez-nao-planejada-custa-r-41-bilhoes-por-ano-para-o-brasil-3103\n2017 Somente o amplo conhecimento sobre os métodos contraceptivos e seu uso pode mudar\nessa situação. Assinale a afirmativa correta:","options":{"A":"Os dispositivos intrauterinos devem, obrigatoriamente, ser inseridos durante o período\nmenstrual.","B":"Os dispositivos intrauterinos são contraindicados para uso em nulíparas.","C":"O termo contraceptivo hormonal se refere medicações que contêm estrogênio e progesterona ou\nsomente progesterona. Podem ser administrados na forma de contracepção oral, adesivo, implante\ne injeção.","D":"O uso de progesterona isolada como método contraceptivo deve ser apenas realizado durante o\naleitamento materno exclusivo, devido sua baixa eficácia contraceptiva fora desse período.","E":"O uso prolongado de contracepção oral combinada aumenta o risco de câncer de mama,\nendométrio e ovário."},"answer":"C","answerPending":false,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-172786","number":"172786","sourceNumber":"172786","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"O dispositivo intra-uterino de cobre não deve ser utilizado de forma indiscriminada.\nAvalie as situações abaixo: I- Útero bicomo; II-\nNuliparidade; III- Sangramento genital de origem\ndesconhecida; IV- Tabagismo. Qual dessas situações são consideradas contra-indicações\nabsolutas?","options":{"A":"I e III apenas.","B":"II e III apenas.","C":"I, II e III apenas.","D":"I, II, III e IV."},"answer":"A","answerPending":false,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-188040","number":"188040","sourceNumber":"188040","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Mulher, 19 anos procura unidade de saúde por se queixar de rompimento de\npreservativo durante ato sexual ocorrido há\n1(um) dia, época em que se encontrava no meio do seu\nciclo menstrual. Que orientação é adequada para o caso considerando que a paciente não quer\nengravidar?","options":{"A":"Pouco pode ser feito, uma vez que o esperma alterou o muco cervical.","B":"A probabilidade de gravidez sem método contraceptivo é de 5%.","C":"O uso de contracepção oral de emergência é eficaz na prevenção da gravidez.","D":"Para prevenir a gravidez deve fazer uso de anticoncepcional durante dois dias.","E":"A ducha pós-coito é uma opção eficaz na prevenção da gravidez."},"answer":"C","answerPending":false,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-187445","number":"187445","sourceNumber":"187445","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Dos métodos contraceptivos abaixo, o mais indicado para uma paciente com trombofilia\nhereditária é:","options":{"A":"Injetável Mensal;","B":"Pílula Combinada Oral;","C":"Anel Hormonal Vaginal;","D":"Adesivo Hormonal Contraceptivo;","E":"D.I.U;"},"answer":"E","answerPending":false,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-155456","number":"155456","sourceNumber":"155456","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Paciente de 46 anos, GII PII A0, ciclos menstruais regulares, nega qualquer queixa\nginecológica. Realizou inserção de DIU de cobre para contracepção há 1 semana. Ultrassonografia\npélvica realizada para avaliar o posicionamento do DIU evidenciou presença de 2 imagens\nhipoecoicas e heterogêneas, de limites bem definidos no miométrio: uma intramural em parede\nanterior de 1,5 cm a outra de 2,2 cm subserosa em parede fúndica. O DIU estava\nnormoposicionado. Frente a esta situação devemos:","options":{"A":"Manter conduta expectante e realizar avaliações periódicas da paciente.","B":"Indicar miomectomia laparoscópica e troca do DIU de cobre por DIU de Levonorgestrel.","C":"Indicar miomectomia histeroscópica e troca do DIU de cobre por DIU de Levonorgestrel.","D":"Indicar histerectomia.","E":"Indicar miomectomia por laparotomia e manutenção do DIU de cobre."},"answer":"A","answerPending":false,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-162582","number":"162582","sourceNumber":"162582","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Dos métodos contraceptivos abaixo, NÃO está recomendado para pacientes\nsubmetidos à Cirurgia Bariátrica:","options":{"A":"Injetável Mensal.","B":"Pílula Combinada Oral;","C":"Anel Hormonal Vaginal.","D":"Adesivo Hormonal Contraceptivo.","E":"D.I.U."},"answer":"B","answerPending":false,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-137849","number":"137849","sourceNumber":"137849","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Entre os métodos contraceptivos, os dispositivos intrauterinos (DIUs) têm papel\nimportante pois são muito eficazes, com taxas de\ngravidez inferiores a 0,2 por 100 mulheres/ano.\nSobre eles é INCORRETO afirmar:","options":{"A":"O DIU de cobre é aprovado para uso contínuo por 10 anos , enquanto o de levonorgestrel é\naprovado para uso contínuo por 5 anos.","B":"Não são abortivos.","C":"Embora idealmente seja inserido no período menstrual, pode ser inserido em qualquer fase do\nciclo desde que seja possível excluir gravidez.","D":"Anomalias anatômicas do útero são uma das contra-indicações para seu uso.","E":"Provocam aumento das taxas de gravidez ectópica."},"answer":"E","answerPending":false,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-127156","number":"127156","sourceNumber":"127156","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"<p>Paciente com 26 anos, apresentando Lúpus Eritematoso Sistêmico e com\nanticorpos anticardiolipina (aCL) e anticoagulante lúpico (AL) positivos, deseja um método\ncontraceptivo. Qual o método mais seguro para essa paciente?</p>","options":{"A":"Anticoncepcional hormonal combinado.","B":"Progestágenos isolados trimestrais.","C":"Minipílulas.","D":"DIU (Dispositivo Intrauterino) de cobre.","E":"DIU com levonogestrel."},"answer":"A","answerPending":false,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-106425","number":"106425","sourceNumber":"106425","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Entre as patologias ginecológicas que podem causar sangramentos vaginais\npatológicos no menacme, podemos citar, EXCETO:","options":{"A":"câncer de colo uterino;","B":"pólipo endometrial;","C":"miomatose;","D":"cervicite;","E":"tuberculose genital."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-88874","number":"88874","sourceNumber":"88874","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Considere as seguintes afirmativas quanto ao sangramento uterino anormal: I. Cerca de\n20% dos casos de sangramento uterino em\nadolescentes relacionam-se a algum tipo de discrasia\nsanguínea. II. A possibilidade de doença uterina aumenta com a faixa etária. III. O sangramento\ndisfuncional deve-se geralmente a ciclos anovulatórios. Quais estão corretas?","options":{"A":"Apenas I.","B":"Apenas I e II.","C":"Apenas I e III.","D":"Apenas II e III.","E":"I, II e III."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-88901","number":"88901","sourceNumber":"88901","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Considere os exames abaixo: I. Mamografia para rastreamento do câncer de mama. II.\nPerfil lipídico para rastreamento das dislipidemias e escolha da melhor via de administração da\nterapia hormonal. III. Ultrassonografia transvaginal ou teste do progestogênio para avaliação do\nendométrio. Quais métodos propedêuticos devem ser solicitados na avaliação da paciente\nclimatérica antes da prescrição da terapia hormonal?","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas III.","D":"Apenas I e II.","E":"I, II e III."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-77493","number":"77493","sourceNumber":"77493","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"Paciente de 36 anos, Gesta 0, Para 0, foi submetida à histerectomia total abdominal\ncom ooforectomia bilateral devido à endometriose\nsevera. Apresenta após 30 dias da cirurgia,\nondas de calor que incomodam bastante, sudorese, insônia, ressecamento vaginal, desânimo, falta\nde energia e humor depressivo. Qual a melhor conduta?","options":{"A":"Não fazer Terapia Hormonal (TH) do climatério pelo passado de endometriose.","B":"Fazer TH com estrogênio puro, oral ou transdérmico.","C":"Fazer TH com estrogênio e androgênio.","D":"Fazer TH com progesterona e androgênio.","E":"Fazer TH com estrogênio, progesterona e androgênio."},"answer":"","answerPending":true,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-77529","number":"77529","sourceNumber":"77529","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"São contraindicações absolutas do uso do dispositivo intrauterino de cobre, exceto:","options":{"A":"Doença inflamatória pélvica atual.","B":"Útero bicorno.","C":"Gravidez.","D":"Tabagismo.","E":"Sangramento genital de origem desconhecida."},"answer":"D","answerPending":false,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-05-59066","number":"59066","sourceNumber":"59066","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-05","collectionLabel":"MED · MED GIN 05","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 05","subtopic":"","stem":"A respeito da contracepção em mães que amamentam exclusivamente, podemos\nafirmar:","options":{"A":"O retorno das ovulações demoram em média 45 dias pós-parto em mães lactantes.","B":"O progestágeno desogestrel (etanogestrel) usado de forma continua não diminui a quantidade\nde leite.","C":"A amenorreia lactacional tem eficácia de 50% na anticoncepção, se seguirmos critérios rígidos.","D":"Os anticoncepcionais combinados de estrógenos e progestágenos não afetam a qualidade e\nquantidade do leite materno.","E":"Os anticoncepcionais combinados com drosperinona ou gestodemo são os mais indicados se\n\nusados de forma contínua."},"answer":"B","answerPending":false,"source":"Gineco e obstetricia/MED GIN 05/MED GIN 05.txt","sourceLabel":"MED · MED GIN 05","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 05","MED"],"answerSource":"explicit","commentDeferred":true}]};
